<div class="grid gap-5 sm:grid-cols-2">
    <label class="text-sm font-medium text-slate-700 sm:col-span-2">Rule name <span class="text-red-700">*</span><input class="mt-1 block min-h-11 w-full border-slate-300" name="name" value="{{ old('name', $pricingRule->name) }}" maxlength="255" required></label>
    <label class="text-sm font-medium text-slate-700 sm:col-span-2">Description<textarea class="mt-1 block w-full border-slate-300" name="description" rows="3" maxlength="2000">{{ old('description', $pricingRule->description) }}</textarea></label>
    <label class="text-sm font-medium text-slate-700">Fixed extra charge (€) <span class="text-red-700">*</span><input class="mt-1 block min-h-11 w-full border-slate-300" name="extra_charge" type="number" min="0" max="1000000" step="0.01" value="{{ old('extra_charge', $pricingRule->extra_charge ?? '0.00') }}" required></label>
    <label class="text-sm font-medium text-slate-700">Status <select class="mt-1 block min-h-11 w-full border-slate-300" name="status" required><option value="active" @selected(old('status', $pricingRule->status ?: 'active') === 'active')>Active</option><option value="inactive" @selected(old('status', $pricingRule->status) === 'inactive')>Inactive</option></select></label>
    <label class="text-sm font-medium text-slate-700">Starts at <span class="font-normal text-slate-500">Optional</span><input class="mt-1 block min-h-11 w-full border-slate-300" name="starts_at" type="datetime-local" value="{{ old('starts_at', $pricingRule->starts_at?->format('Y-m-d\TH:i')) }}"></label>
    <label class="text-sm font-medium text-slate-700">Ends at <span class="font-normal text-slate-500">Optional</span><input class="mt-1 block min-h-11 w-full border-slate-300" name="ends_at" type="datetime-local" value="{{ old('ends_at', $pricingRule->ends_at?->format('Y-m-d\TH:i')) }}"></label>
</div>
